      if (a === 'addjob') return win('Create: Backup Job', () => `<div class="tabs"><span class="on">General</span><span>Retention</span></div><div class="fg"><label>Node: <select><option>-- All --</option></select></label><label>Storage: <select id="dSt">${P.storages.map((s) => `<option>${s.id}</option>`).join('')}</select></label><label>Schedule: <select id="dSc"><option>00:00</option><option>01:00</option><option>sat 18:15</option><option>*/30</option></select></label><label>Selection mode: <select id="dSm"><option>Include selected VMs</option><option>All</option></select></label><label>Mode: <select id="dMo"><option>Snapshot</option><option>Suspend</option><option>Stop</option></select></label><label>Compression: <select id="dCo"><option>ZSTD (fast and good)</option><option>LZO (fast)</option><option>GZIP (good)</option><option>none</option></select></label><label>Keep Daily: <input type="number" id="dKd"></label><label>Keep Weekly: <input type="number" id="dKw"></label></div><div style="margin-top:6px">${P.vms.map((x) => `<label style="margin-right:12px"><input type="checkbox" class="dVm" value="${x.id}"> ${x.id} ${x.name}</label>`).join('')}</div>`, () => { const sm = g('dSm').selectedIndex, ids = sm ? P.vms.map((x) => x.id) : [...host.querySelectorAll('.dVm:checked')].map((x) => +x.value); P.jobs.push({ storage: g('dSt').value, sched: g('dSc').value, sel: ids, mode: g('dMo').value, comp: g('dCo').value.split(' ')[0], kd: +g('dKd').value || 0, kw: +g('dKw').value || 0 }); }, 'Create');
